## 平台特定代码

```csharp
// 检测平台
if (RuntimeInformation.IsOSPlatform(OSPlatform.Windows))
{
    // Windows 特定
}
else if (RuntimeInformation.IsOSPlatform(OSPlatform.Linux))
{
    // Linux 特定
}
else if (RuntimeInformation.IsOSPlatform(OSPlatform.OSX))
{
    // macOS 特定
}

// 使用条件编译
#if WINDOWS
    // Windows 特定
#elif LINUX
    // Linux 特定
#endif
```

## 原生互操作

```csharp
// 调用原生代码
[DllImport("user32.dll")]
static extern IntPtr GetForegroundWindow();

// 使用平台 API
#if WINDOWS
    var window = GetForegroundWindow();
#endif
```

## 打包和发布

```bash
# Windows
 dotnet publish -c Release -r win-x64 --self-contained

# macOS
 dotnet publish -c Release -r osx-x64 --self-contained

# Linux
 dotnet publish -c Release -r linux-x64 --self-contained
```

## 与 MAUI 对比

**Avalonia 优势**：
- 支持 Linux
- 更接近 WPF 体验
- 自定义渲染引擎（UI 一致性好）
- 支持 WebAssembly

**MAUI 优势**：
- 微软官方支持
- 原生控件（平台一致性好）
- 移动平台优化
- 更大的生态系统

## 取舍与选型
Avalonia 自绘控件的好处是「一套 UI 各平台像素级一致」，不用为各平台控件差异适配、维护一套代码；代价是和系统原生体验有差距——原生右键菜单、无障碍（屏幕阅读器）、输入法 IME、系统主题跟随这些贴合度不如原生控件，还带着渲染引擎、包体积偏大。这正是它和 MAUI 的根本取舍：Avalonia 选一致性，MAUI 选原生贴合。选型：只做 Windows 桌面用成熟的 WPF；要跨桌面三端、尤其要支持 Linux、要 UI 一致用 Avalonia；移动优先或要原生体验用 MAUI。

using System;
using System.Collections.ObjectModel;
using System.Runtime.InteropServices;
using Avalonia;
using Avalonia.Controls;
using Avalonia.Interactivity;
using Avalonia.Markup.Xaml;
using CommunityToolkit.Mvvm.ComponentModel;
using CommunityToolkit.Mvvm.Input;

namespace AvaloniaDemo
{
    // ViewModel
    public partial class MainWindowViewModel : ObservableObject
    {
        [ObservableProperty]
        private string _title = "Hello Avalonia";

        [ObservableProperty]
        private string _inputText = string.Empty;

        [ObservableProperty]
        private ObservableCollection<TodoItem> _todoItems = new();

        [ObservableProperty]
        private TodoItem? _selectedItem;

        [ObservableProperty]
        private string _platformInfo = string.Empty;

        public MainWindowViewModel()
        {
            // 添加示例数据
            TodoItems.Add(new TodoItem { Title = "学习 Avalonia", IsCompleted = false });
            TodoItems.Add(new TodoItem { Title = "创建跨平台应用", IsCompleted = false });
            TodoItems.Add(new TodoItem { Title = "部署到生产环境", IsCompleted = false });

            // 获取平台信息
            PlatformInfo = $"OS: {RuntimeInformation.OSDescription}, " +
                           $"Architecture: {RuntimeInformation.OSArchitecture}";
        }

        [RelayCommand]
        private void AddItem()
        {
            if (!string.IsNullOrWhiteSpace(InputText))
            {
                TodoItems.Add(new TodoItem
                {
                    Title = InputText,
                    IsCompleted = false
                });
                InputText = string.Empty;
            }
        }

        [RelayCommand]
        private void RemoveItem(TodoItem? item)
        {
            if (item != null)
            {
                TodoItems.Remove(item);
            }
        }

        [RelayCommand]
        private void ToggleComplete(TodoItem? item)
        {
            if (item != null)
            {
                item.IsCompleted = !item.IsCompleted;
            }
        }
    }

    // Model
    public partial class TodoItem : ObservableObject
    {
        [ObservableProperty]
        private string _title = string.Empty;

        [ObservableProperty]
        private bool _isCompleted;
    }

    // 自定义控件
    public class MyCustomControl : Control
    {
        public static readonly StyledProperty<string> TextProperty =
            AvaloniaProperty.Register<MyCustomControl, string>(nameof(Text));

        public static readonly StyledProperty<double> FontSizeProperty =
            AvaloniaProperty.Register<MyCustomControl, double>(nameof(FontSize), 12);

        public string Text
        {
            get => GetValue(TextProperty);
            set => SetValue(TextProperty, value);
        }

        public double FontSize
        {
            get => GetValue(FontSizeProperty);
            set => SetValue(FontSizeProperty, value);
        }

        public override void Render(DrawingContext context)
        {
            base.Render(context);
            // 自定义渲染逻辑
        }
    }

    // View
    public partial class MainWindow : Window
    {
        public MainWindow()
        {
            InitializeComponent();
#if DEBUG
            this.AttachDevTools();
#endif
        }

        private void InitializeComponent()
        {
            AvaloniaXamlLoader.Load(this);
        }

        private void OnAddClick(object? sender, RoutedEventArgs e)
        {
            if (DataContext is MainWindowViewModel viewModel)
            {
                viewModel.AddItemCommand.Execute(null);
            }
        }

        private void OnKeyDown(object? sender, Avalonia.Input.KeyEventArgs e)
        {
            if (e.Key == Avalonia.Input.Key.Enter)
            {
                OnAddClick(sender, e);
            }
        }
    }

    // App
    public class App : Application
    {
        public override void Initialize()
        {
            AvaloniaXamlLoader.Load(this);
        }

        public override void OnFrameworkInitializationCompleted()
        {
            if (ApplicationLifetime is Avalonia.Controls.ApplicationLifetimes.IClassicDesktopStyleApplicationLifetime desktop)
            {
                desktop.MainWindow = new MainWindow
                {
                    DataContext = new MainWindowViewModel()
                };
            }

            base.OnFrameworkInitializationCompleted();
        }
    }

    // Program
    class Program
    {
        [STAThread]
        public static void Main(string[] args)
        {
            BuildAvaloniaApp()
                .StartWithClassicDesktopLifetime(args);
        }

        public static AppBuilder BuildAvaloniaApp()
            => AppBuilder.Configure<App>()
                .UsePlatformDetect()
                .LogToTrace();
    }

    // 服务接口
    public interface IPlatformService
    {
        string GetPlatformName();
        bool IsWindows();
        bool IsLinux();
        bool IsMacOS();
    }

    // 平台服务实现
    public class PlatformService : IPlatformService
    {
        public string GetPlatformName()
        {
            if (RuntimeInformation.IsOSPlatform(OSPlatform.Windows))
                return "Windows";
            if (RuntimeInformation.IsOSPlatform(OSPlatform.Linux))
                return "Linux";
            if (RuntimeInformation.IsOSPlatform(OSPlatform.OSX))
                return "macOS";
            return "Unknown";
        }

        public bool IsWindows() => RuntimeInformation.IsOSPlatform(OSPlatform.Windows);
        public bool IsLinux() => RuntimeInformation.IsOSPlatform(OSPlatform.Linux);
        public bool IsMacOS() => RuntimeInformation.IsOSPlatform(OSPlatform.OSX);
    }

    // 依赖注入配置
    public static class ServiceCollectionExtensions
    {
        public static IServiceCollection AddAvaloniaServices(this IServiceCollection services)
        {
            services.AddSingleton<IPlatformService, PlatformService>();
            services.AddTransient<MainWindowViewModel>();
            return services;
        }
    }
}
